svg.script:
(function () {
  var names = ["index.html", "Why.html", "whyrevived.html"];
  var frame = document.getElementById("app");
  function next(i) {
    if (!frame || i >= names.length) return;
    fetch(names[i], { method: "GET" }).then(function (res) {
      if (!res.ok) { next(i + 1); return; }
      frame.setAttribute("src", names[i]);
    }, function () { next(i + 1); });
  }
  next(0);
})();
